import test from "node:test";
import assert from "node:assert/strict";
import {fixture} from "./fixture.mjs";
import {MemoryDecisionLedger,authorizeDecision,consumeAuthorization} from "../ledger.mjs";
const now=Date.parse("2026-10-12T12:00:00Z");
function setup(){const f=fixture();f.policy.reservationTtlSeconds=60;f.policy.approvalReference="fixture-approval";f.intent.operation="transfer";f.intent.quantityBaseUnits="100";return f;}
function fresh(f,time){const s=structuredClone(f.state);for(const e of Object.values(s.evidence))e.observedAt=new Date(time).toISOString();for(const w of s.velocity){w.asOf=time;w.completeSince=time-w.seconds*1000;}return s;}
async function reserve(f,ledger,key,time=now){return authorizeDecision({ledger,policy:f.policy,intent:f.intent,idempotencyKey:key,now:time,loadCanonical:async()=>fresh(f,time)});}
test("expired unused reservations release capacity and retain an auditable non-reusable identity",async()=>{const f=setup(),ledger=new MemoryDecisionLedger();const old=await Promise.all(Array.from({length:6},(_,i)=>reserve(f,ledger,"old-"+i)));assert.equal(old.filter(r=>r.executionAllowed).length,6);const next=await reserve(f,ledger,"new",now+61000);assert.equal(next.executionAllowed,true);assert.equal(ledger.list().filter(r=>r.status==="EXPIRED").length,6);const replay=await reserve(f,ledger,"old-0",now+61000);assert.equal(replay.authorizationId,old[0].authorizationId);assert.equal(replay.executionAllowed,false);assert.ok(ledger.audit.some(r=>r.event==="expire"));});
test("expiry is a hard consumption gate even when a revalidation callback returns true",async()=>{const f=setup(),ledger=new MemoryDecisionLedger(),row=await reserve(f,ledger,"one");await assert.rejects(()=>consumeAuthorization(ledger,row.authorizationId,row.intentDigest,async()=>true,()=>now+60000),/EXPIRED/);assert.equal(ledger.list()[0].status,"RESERVED");});
test("consumed or uncertain execution retains capacity after the reservation deadline",async()=>{const f=setup(),ledger=new MemoryDecisionLedger(),row=await reserve(f,ledger,"consumed");await consumeAuthorization(ledger,row.authorizationId,row.intentDigest,async()=>true,()=>now);await Promise.all(Array.from({length:5},(_,i)=>reserve(f,ledger,"unused-"+i)));const next=await Promise.all(Array.from({length:6},(_,i)=>reserve(f,ledger,"new-"+i,now+61000)));assert.equal(next.filter(r=>r.executionAllowed).length,5);assert.equal(ledger.list().find(r=>r.authorizationId===row.authorizationId).status,"CONSUMED");});
test("a replaced policy releases only unconsumed reservations within its asset and chain scope",async()=>{const f=setup(),ledger=new MemoryDecisionLedger();await Promise.all(Array.from({length:6},(_,i)=>reserve(f,ledger,"old-"+i)));f.policy.version="FIXTURE-MI-2";f.policy.approvalReference="fixture-new-approval";const next=await reserve(f,ledger,"new",now+1000);assert.equal(next.executionAllowed,true);assert.equal(ledger.list().filter(r=>r.status==="POLICY_INVALIDATED").length,6);});
